  v_item jsonb;
  v_brand_id uuid;
  v_current jsonb;
  v_field record;
  v_change_count integer;
  v_patch_size integer;
  v_event_count_before bigint;
  v_event_count_after bigint;
begin
  select count(*)
  into v_change_count
  from jsonb_array_elements(v_manifest -> 'changes') as change_item
  cross join lateral jsonb_object_keys(change_item -> 'patch');

  if v_change_count <> 228 then
    raise exception 'Reviewed link manifest has % changes; expected 228', v_change_count;
  end if;

  if jsonb_array_length(v_manifest -> 'holds') <> 14 then
    raise exception 'Reviewed link manifest has % holds; expected 14',
      jsonb_array_length(v_manifest -> 'holds');
  end if;

  for v_item in
    select value from jsonb_array_elements(v_manifest -> 'holds')
  loop
    select b.id, to_jsonb(b)
    into v_brand_id, v_current
    from public.brands b
    where b.slug = v_item ->> 'slug'
    for update;

    if not found then
      raise exception 'Held brand slug not found: %', v_item ->> 'slug';
    end if;

    if v_current ->> 'name' is distinct from v_item ->> 'name' then
      raise exception 'Held brand identity mismatch for slug %', v_item ->> 'slug';
    end if;

    for v_field in select key, value from jsonb_each(v_item -> 'expected')
    loop
      if not (v_current ? v_field.key) then
        raise exception 'Unknown held brand field %.%', v_item ->> 'slug', v_field.key;
      end if;
      if v_current -> v_field.key is distinct from v_field.value then
        raise exception 'Held value changed for %.%: expected %, found %',
          v_item ->> 'slug', v_field.key, v_field.value, v_current -> v_field.key;
      end if;
    end loop;
  end loop;

  for v_item in
    select value from jsonb_array_elements(v_manifest -> 'changes')
  loop
    select b.id, to_jsonb(b)
    into v_brand_id, v_current
    from public.brands b
    where b.slug = v_item ->> 'slug'
    for update;

    if not found then
      raise exception 'Target brand slug not found: %', v_item ->> 'slug';
    end if;

    if v_current ->> 'name' is distinct from v_item ->> 'name' then
      raise exception 'Target brand identity mismatch for slug %', v_item ->> 'slug';
    end if;

    for v_field in select key, value from jsonb_each(v_item -> 'expected')
    loop
      if not (v_current ? v_field.key) then
        raise exception 'Unknown target brand field %.%', v_item ->> 'slug', v_field.key;
      end if;
      if v_current -> v_field.key is distinct from v_field.value then
        raise exception 'Target value changed for %.%: expected %, found %',
          v_item ->> 'slug', v_field.key, v_field.value, v_current -> v_field.key;
      end if;
    end loop;

    for v_field in select key, value from jsonb_each(v_item -> 'patch')
    loop
      if v_current -> v_field.key is not distinct from v_field.value then
        raise exception 'Reviewed patch is a no-op for %.%', v_item ->> 'slug', v_field.key;
      end if;
    end loop;

    select count(*) into v_event_count_before
    from public.brand_field_events
    where brand_id = v_brand_id;

    perform public.apply_brand_patch(
      v_brand_id,
      v_item -> 'patch',
      'admin',
      null::uuid,
      null::uuid
    );

    select count(*) into v_event_count_after
    from public.brand_field_events
    where brand_id = v_brand_id;

    select count(*) into v_patch_size
    from jsonb_object_keys(v_item -> 'patch');

    if v_event_count_after - v_event_count_before <> v_patch_size then
      raise exception 'Audit event count mismatch for %', v_item ->> 'slug';
    end if;
  end loop;
end;
